const msg = $json.message;
const text = (msg && msg.text || '').trim();
const parts = text.split(/\s+/);
const command = (parts[0] || '').toLowerCase();
const content = parts.slice(1).join(' ').trim();
const from = msg.from || {};

return {
  json: {
    command,
    // idea_text: kept exactly as-is so the existing /idea branch is untouched.
    idea_text: content,
    // content_text: generic alias of the same value, used by the other five
    // command branches (question/suggestion/decision/action/observation) so
    // they don't each need their own copy of this parsing logic.
    content_text: content,
    // Display-only attribution (matches 07_DATABASE_SCHEMA.md's MVP scope note:
    // Telegram participants are identified by raw username/first name, not a
    // persistent account ID - no account linking exists in the MVP).
    telegram_display_name: from.username || from.first_name || 'unknown',
    chat_id: msg.chat.id,
    // Group name, not personal data - only present for groups/supergroups,
    // not private chats (msg.chat.title is undefined there).
    chat_title: msg.chat.title || null,
    message_id: msg.message_id
  }
};

const res = $json;
const isNew = res.status === 'saved';
const text = isNew
  ? `✅ Idea saved!\n📌 ${res.title}\n${res.summary}`
  : `ℹ️ ${res.title || 'This looks similar to an existing idea'}\n${res.summary || 'A similar idea already exists — nothing new was saved.'}`;

return { json: { reply_text: text, status: res.status, similar_found: res.similar_found } };

const content = $json.content_text;
const instructions = `You are extracting a QUESTION raised in a Telegram discussion for a training program's manager dashboard. A Question is something that needs an answer from someone else, especially if it is blocking progress. Your job is to preserve what was asked - you never answer the question yourself, and you never guess who should respond or what the answer might be.

Read the submitted message and produce:
- title: a short, specific title (under 8 words)
- summary: the question itself, restated clearly if needed, but not answered or resolved
- is_blocking: true ONLY if the message explicitly says this is urgent, blocking, or needed before something else can proceed. Do not infer urgency from tone or phrasing alone - if it is not stated, use false.
- addressed_to: the specific person or role the question is directed at, ONLY if explicitly named in the message (e.g. a mention, or "can someone from the design team..."). If no one is named, use null. Never guess who should answer.
- tags: short lowercase topical labels
- keywords: key terms useful for future search

Never add information, an answer, or a name that is not present in the message. Respond with JSON only, matching the given schema exactly.`;
return { json: { ...$json, ai_prompt: `${instructions}

Submitted question:
${content}` } };

const raw = $json.candidates?.[0]?.content?.parts?.[0]?.text;
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  return { json: { status: 'error', title: '', summary: 'Could not parse the AI response - please try again.', is_blocking: false, addressed_to: null, tags: [], keywords: [] } };
}
const ok = parsed && typeof parsed.title === 'string' && typeof parsed.summary === 'string' && typeof parsed.is_blocking === 'boolean' && Array.isArray(parsed.tags) && Array.isArray(parsed.keywords);
if (!ok) {
  return { json: { status: 'error', title: '', summary: 'AI response was missing required fields - please try again.', is_blocking: false, addressed_to: null, tags: [], keywords: [] } };
}
return { json: { status: 'ok', title: parsed.title, summary: parsed.summary, is_blocking: parsed.is_blocking, addressed_to: parsed.addressed_to ?? null, tags: parsed.tags, keywords: parsed.keywords } };

const v = $('Validate Question Output').item.json;
if (v.status !== 'ok') {
  return { json: { reply_text: `⚠️ ${v.summary}` } };
}
let text = v.is_blocking
  ? `🚨 Question saved (blocking)!
📌 ${v.title}
${v.summary}`
  : `❓ Question saved!
📌 ${v.title}
${v.summary}`;
if (v.addressed_to) text += `
➡️ For: ${v.addressed_to}`;
return { json: { reply_text: text } };

const content = $json.content_text;
const instructions = `You are extracting a SUGGESTION raised in a Telegram discussion for a training program's manager dashboard. A Suggestion proposes a change or improvement to something that already exists - it is not a brand-new idea. Your job is to preserve what should change and why - never invent a justification the submitter did not give, and never turn this into a new-idea pitch.

Read the submitted message and produce:
- title: a short, specific title (under 8 words)
- summary: one to two sentences describing what should change and, only if stated, why
- target: the existing thing being improved (a feature, process, document, etc.), ONLY if explicitly named in the message. If it is not named, use null. Never guess what it targets.
- tags: short lowercase topical labels
- keywords: key terms useful for future search

Never add information not present in the message. Respond with JSON only, matching the given schema exactly.`;
return { json: { ...$json, ai_prompt: `${instructions}

Submitted suggestion:
${content}` } };

